393	        let items = vec![system("be helpful"), user(vec![text("hi")])];
394	        let tm = items_to_messages(&items).unwrap();
395	        assert_eq!(tm.system.len(), 1);
396	        assert!(matches!(&tm.system[0], SystemContentBlock::Text(t) if t == "be helpful"));
397	        assert_eq!(tm.messages.len(), 1);
