572	    fn assistant_message_followed_by_tool_call_stays_on_same_assistant_turn() {
573	        // Item::AssistantMessage + Item::ToolCall → single assistant message with both blocks.
574	        // AssistantMessage is pushed as an assistant turn, then ToolCall queues to
575	        // pending_assistant, which at end-of-input is flushed and coalesced into the
576	        // existing assistant turn.
577	        let items = vec![
578	            user(vec![text("do it")]),
579	            assistant(vec![text("ok, calling tool")]),
580	            Item::ToolCall {
581	                call_id: "tu_1".to_owned(),
582	                name: "ping".to_owned(),
583	                args: json!({}),
584	            },
585	        ];
586	        let w = wire(&items).unwrap();
587	        let msgs = w["messages"].as_array().unwrap();
588	        // user + one assistant turn (text + tool_use coalesced)
589	        assert_eq!(
590	            msgs.len(),
591	            2,
592	            "assistant text + tool_call must be one assistant turn"
593	        );
594	        assert_eq!(msgs[0]["role"], "user");
595	        assert_eq!(msgs[1]["role"], "assistant");
596	        let content = msgs[1]["content"].as_array().unwrap();
597	        assert_eq!(
598	            content.len(),
599	            2,
600	            "assistant turn has text block + tool_use block"
601	        );
602	        assert_eq!(content[0]["type"], "text");
603	        assert_eq!(content[1]["type"], "tool_use");
604	    }
