83	/// Assemble a [`PreparedConverse`] from the builder `Config` and a [`ModelRequest`].
84	///
85	/// # Errors
86	/// - Reserved tool name (`__paigasus_structured_output__` used by the caller).
87	/// - `ResponseFormat::JsonSchema`/`JsonObject` combined with `ToolChoice::Tool` (conflict).
88	/// - `ResponseFormat::JsonSchema`/`JsonObject` combined with `ToolChoice::None` (conflict).
89	/// - Empty conversation (no non-system messages).
90	pub(crate) fn build_request(
91	    cfg: &Config,
92	    req: &ModelRequest,
93	) -> Result<PreparedConverse, ModelError> {
94	    let family = cfg.family;
95	    let ruleset = Ruleset::for_family(family);
96	
97	    // Guard: ResponseFormat::JsonSchema / JsonObject + ToolChoice::Tool → conflict.
98	    let synthesizing_rf = matches!(
99	        req.model_settings.response_format.as_ref(),
100	        Some(paigasus_helikon_core::ResponseFormat::JsonSchema { .. })
101	            | Some(paigasus_helikon_core::ResponseFormat::JsonObject),
102	    );
103	    let forced_tool = matches!(
104	        req.model_settings.tool_choice.as_ref(),
105	        Some(ToolChoice::Tool { .. }),
106	    );
107	    if synthesizing_rf && family.supports_forced_tool_choice() && forced_tool {
108	        return Err(ModelError::Other(anyhow::anyhow!(
109	            "ResponseFormat::JsonSchema/JsonObject and ToolChoice::Tool are mutually \
110	             exclusive on Bedrock — use one or the other",
111	        )));
112	    }
113	
114	    // Guard: ResponseFormat::JsonSchema / JsonObject + ToolChoice::None → conflict.
115	    // Synthesis requires injecting a tool; ToolChoice::None suppresses toolConfig entirely.
116	    let none_choice = matches!(
117	        req.model_settings.tool_choice.as_ref(),
118	        Some(ToolChoice::None),
119	    );
120	    if synthesizing_rf && family.supports_forced_tool_choice() && none_choice {
121	        return Err(ModelError::Other(anyhow::anyhow!(
122	            "ResponseFormat::JsonSchema/JsonObject and ToolChoice::None are mutually \
123	             exclusive on Bedrock — structured-output synthesis requires a tool call",
124	        )));
125	    }
126	
127	    // ToolChoice::None means the model MUST NOT call any tool this turn.
128	    // Omit toolConfig entirely (do not send user tools either).
129	    if none_choice {
130	        let translated = items_to_messages(&req.messages)?;
131	        let inference_config = build_inference_config(req, cfg);
132	        return Ok(PreparedConverse {
133	            model_id: cfg.model_id.clone(),
134	            system: translated.system,
135	            messages: translated.messages,
136	            tool_config: None,
137	            inference_config,
138	            synthesizing: false,
139	        });
140	    }
141	
142	    // Translate messages.
143	    let translated = items_to_messages(&req.messages)?;
144	
145	    // Translate user tool defs (also validates reserved name).
146	    let user_specs = tool_specs(&req.tools, ruleset)?;
147	
148	    // Synthesize structured output tool (if applicable).
149	    let Synthesized {
150	        tool: synth_tool,
151	        tool_choice: synth_tc,
152	        synthesizing,
153	    } = synthesize(req.model_settings.response_format.as_ref(), family, ruleset)?;
154	
155	    // Merge tool lists: user tools first, synthesized appended.
156	    let mut all_tools: Vec<Tool> = user_specs.into_iter().map(Tool::ToolSpec).collect();
157	    if let Some(st) = synth_tool {
158	        all_tools.push(Tool::ToolSpec(st));
159	    }
160	
161	    // Build ToolConfiguration (only when there are tools or a tool_choice).
162	    let caller_tc = req
163	        .model_settings
164	        .tool_choice
165	        .as_ref()
166	        .and_then(|tc| translate_tool_choice(tc, family));
167	
168	    // Synthesis overrides caller tool_choice.
169	    // synth_tool.is_some() always pushes to all_tools above, so a synthesized tool_choice is never silently dropped here.
170	    let effective_tc = synth_tc.or(caller_tc);
171	
172	    // Validate forced tool choices on supported families.
173	    // (On unsupported families, forced choices were already omitted by translate_tool_choice.)
174	    if family.supports_forced_tool_choice() {
175	        match req.model_settings.tool_choice.as_ref() {
176	            Some(ToolChoice::Required) if !synthesizing => {
177	                if all_tools.is_empty() {
178	                    return Err(ModelError::Other(anyhow::anyhow!(
179	                        "ToolChoice::Required requires at least one tool to be defined",
180	                    )));
181	                }
182	            }
183	            Some(ToolChoice::Tool { name }) => {
184	                let tool_names: Vec<&str> = all_tools
185	                    .iter()
186	                    .filter_map(|t| {
187	                        if let Tool::ToolSpec(spec) = t {
188	                            Some(spec.name())
189	                        } else {
190	                            None
191	                        }
192	                    })
193	                    .collect();
194	                if !tool_names.contains(&name.as_str()) {
195	                    return Err(ModelError::Other(anyhow::anyhow!(
196	                        "ToolChoice::Tool references tool {:?} which is not defined in the tool list",
197	                        name,
198	                    )));
199	                }
200	            }
201	            _ => {}
202	        }
203	    }
204	
205	    let tool_config = if !all_tools.is_empty() {
206	        let mut builder = ToolConfiguration::builder();
207	        for t in all_tools {
208	            builder = builder.tools(t);
209	        }
210	        if let Some(tc) = effective_tc {
211	            builder = builder.tool_choice(tc);
212	        }
213	        Some(builder.build().map_err(|e| {
214	            ModelError::Other(anyhow::anyhow!("failed to build ToolConfiguration: {e}"))
215	        })?)
216	    } else if effective_tc.is_some() {
217	        // ToolConfiguration requires at least one tool — skip tool_choice when
218	        // no tools are present to avoid a build error.
219	        tracing::debug!(
220	            target: "paigasus::bedrock::translate",
221	            "tool_choice requested but no tools provided; omitting ToolConfiguration",
222	        );
223	        None
224	    } else {
225	        None
226	    };
227	
228	    // Build InferenceConfiguration.
229	    let inference_config = build_inference_config(req, cfg);
230	
231	    Ok(PreparedConverse {
232	        model_id: cfg.model_id.clone(),
233	        system: translated.system,
234	        messages: translated.messages,
235	        tool_config,
236	        inference_config,
237	        synthesizing,
238	    })
239	}
