241	/// Translate a core [`ToolChoice`] into a Bedrock [`BedrockToolChoice`].
242	///
243	/// Returns `None` when the family does not support forced tool choice (the
244	/// `tool_choice` field is omitted from the request). `ToolChoice::None` is
245	/// handled before this function is called (it suppresses `toolConfig` entirely).
246	fn translate_tool_choice(tc: &ToolChoice, family: ModelFamily) -> Option<BedrockToolChoice> {
247	    match tc {
248	        ToolChoice::Auto => Some(BedrockToolChoice::Auto(AutoToolChoice::builder().build())),
249	        ToolChoice::Required => {
250	            if !family.supports_forced_tool_choice() {
251	                tracing::debug!(
252	                    target: "paigasus::bedrock::translate",
253	                    ?family,
254	                    "ToolChoice::Required requested but family does not support forced tool choice; omitting",
255	                );
256	                return None;
257	            }
258	            Some(BedrockToolChoice::Any(AnyToolChoice::builder().build()))
259	        }
260	        ToolChoice::None => {
261	            // ToolChoice::None is handled early in build_request; unreachable here.
262	            None
263	        }
264	        ToolChoice::Tool { name } => {
265	            if !family.supports_forced_tool_choice() {
266	                tracing::debug!(
267	                    target: "paigasus::bedrock::translate",
268	                    ?family,
269	                    tool = %name,
270	                    "ToolChoice::Tool requested but family does not support forced tool choice; omitting",
271	                );
272	                return None;
273	            }
274	            match SpecificToolChoice::builder().name(name).build() {
275	                Ok(s) => Some(BedrockToolChoice::Tool(s)),
276	                Err(e) => {
277	                    tracing::warn!(
278	                        target: "paigasus::bedrock::translate",
279	                        err = %e,
280	                        "failed to build SpecificToolChoice; omitting tool_choice",
281	                    );
282	                    None
283	                }
284	            }
285	        }
286	        _ => {
287	            tracing::debug!(
288	                target: "paigasus::bedrock::translate",
289	                "unknown ToolChoice variant; omitting",
290	            );
291	            None
292	        }
293	    }
294	}
