296	// ── Wire-projection (snapshot tests) ─────────────────────────────────────────
297	
298	/// Project a [`PreparedConverse`] into a stable [`serde_json::Value`] for
299	/// snapshot tests.
300	///
301	/// This projection is deliberately **not** based on `Debug` output of the SDK
302	/// types, which can change across SDK version bumps. Instead, it is a hand-written
303	/// extraction of the semantically relevant fields.
304	#[cfg(test)]
305	pub(crate) fn to_wire_json(p: &PreparedConverse) -> serde_json::Value {
306	    use aws_sdk_bedrockruntime::types::{
307	        ContentBlock, SystemContentBlock, ToolChoice as SdkToolChoice, ToolResultContentBlock,
308	    };
309	    use serde_json::{json, Value};
310	
311	    // System blocks
312	    let system: Vec<Value> = p
313	        .system
314	        .iter()
315	        .map(|s| match s {
316	            SystemContentBlock::Text(t) => json!({"text": t}),
317	            _ => json!({"unknown": true}),
318	        })
319	        .collect();
320	
321	    // Messages
322	    let messages: Vec<Value> = p
323	        .messages
324	        .iter()
325	        .map(|m| {
326	            let role = match m.role {
327	                aws_sdk_bedrockruntime::types::ConversationRole::User => "user",
328	                aws_sdk_bedrockruntime::types::ConversationRole::Assistant => "assistant",
329	                _ => "unknown",
330	            };
331	            let content: Vec<Value> = m
332	                .content
333	                .iter()
334	                .map(|b| match b {
335	                    ContentBlock::Text(t) => json!({"text": t}),
336	                    ContentBlock::ToolUse(tu) => json!({
337	                        "toolUse": {
338	                            "toolUseId": tu.tool_use_id,
339	                            "name": tu.name,
340	                        }
341	                    }),
342	                    ContentBlock::ToolResult(tr) => {
343	                        let text_content = tr
344	                            .content
345	                            .iter()
346	                            .find_map(|c| {
347	                                if let ToolResultContentBlock::Text(t) = c {
348	                                    Some(t.as_str())
349	                                } else {
350	                                    None
351	                                }
352	                            })
353	                            .unwrap_or("");
354	                        json!({
355	                            "toolResult": {
356	                                "toolUseId": tr.tool_use_id,
357	                                "content": [{"text": text_content}],
358	                            }
359	                        })
360	                    }
361	                    _ => json!({"unknown": true}),
362	                })
363	                .collect();
364	            json!({"role": role, "content": content})
365	        })
366	        .collect();
367	
368	    // Tool config
369	    let tool_config: Value = match &p.tool_config {
370	        None => Value::Null,
371	        Some(tc) => {
372	            let tools: Vec<Value> = tc
373	                .tools()
374	                .iter()
375	                .map(|t| match t {
376	                    Tool::ToolSpec(spec) => {
377	                        let schema_placeholder = match spec.input_schema() {
378	                            Some(s) if s.is_json() => json!("<Document>"),
379	                            _ => Value::Null,
380	                        };
381	                        json!({
382	                            "toolSpec": {
383	                                "name": spec.name(),
384	                                "description": spec.description(),
385	                                "inputSchema": {"json": schema_placeholder},
386	                            }
387	                        })
388	                    }
389	                    _ => json!({"unknown": true}),
390	                })
391	                .collect();
392	            let tc_value: Value = match tc.tool_choice() {
393	                None => Value::Null,
394	                Some(SdkToolChoice::Auto(_)) => json!({"auto": {}}),
395	                Some(SdkToolChoice::Any(_)) => json!({"any": {}}),
396	                Some(SdkToolChoice::Tool(s)) => json!({"tool": {"name": s.name()}}),
397	                _ => json!({"unknown": true}),
398	            };
399	            json!({
400	                "tools": tools,
401	                "toolChoice": tc_value,
402	            })
403	        }
404	    };
405	
406	    // Inference config
407	    let inference_config: Value = match &p.inference_config {
408	        None => Value::Null,
409	        Some(ic) => {
410	            let mut m = serde_json::Map::new();
411	            if let Some(t) = ic.temperature() {
412	                m.insert("temperature".into(), json!(t));
413	            }
414	            if let Some(p) = ic.top_p() {
415	                m.insert("topP".into(), json!(p));
416	            }
417	            if let Some(mt) = ic.max_tokens() {
418	                m.insert("maxTokens".into(), json!(mt));
419	            }
420	            Value::Object(m)
421	        }
422	    };
423	
424	    json!({
425	        "modelId": p.model_id,
426	        "system": system,
427	        "messages": messages,
428	        "toolConfig": tool_config,
429	        "inferenceConfig": inference_config,
430	        "synthesizing": p.synthesizing,
431	    })
432	}
