523	            content.push(crate::ContentPart::Text { text });
524	        }
525	        items.push(crate::Item::AssistantMessage {
526	            content,
527	            agent: Some(agent_name.to_owned()),
528	        });
529	    }
530	    for (call_id, accum) in tool_accum {
531	        // OpenAI streaming legitimately emits an empty `arguments` delta for
532	        // zero-parameter tool calls — normalize blank/whitespace-only args to
533	        // `{}` rather than failing the whole turn on a `serde_json` EOF error.
534	        let args_str = if accum.args_str.trim().is_empty() {
535	            "{}"
536	        } else {
537	            accum.args_str.as_str()
538	        };
539	        let args = serde_json::from_str(args_str).map_err(|e| {
540	            format!(
541	                "invalid tool args for call_id={call_id} (name={}): {e}",
542	                accum.name.as_deref().unwrap_or("?")
543	            )
544	        })?;
545	        items.push(crate::Item::ToolCall {
546	            call_id,
547	            name: accum.name.unwrap_or_default(),
548	            args,
549	        });
550	    }
551	    Ok(items)
552	}
553	
554	/// Accumulates a streamed model response into a [`ModelTurn`].
555	///
556	/// Feed every successful [`ModelEvent`] from a [`Model::invoke`] stream via
557	/// [`Self::observe`], then call [`Self::finish`] once the stream ends (after
558	/// observing a `Finish` event) to reassemble the turn's [`crate::Item`]s.
559	#[derive(Debug)]
560	pub struct ModelTurnAccumulator {
561	    agent_name: String,
562	    text: String,
563	    reasoning: String,
564	    tool_accum: std::collections::BTreeMap<String, ToolCallAccum>,
565	    finish_reason: FinishReason,
566	    latest_usage: Option<crate::TokenUsage>,
567	}
568	
569	impl ModelTurnAccumulator {

630	/// performed: this response already transferred to {to}` or `transfer failed:
631	/// {to} did not start`.
632	fn is_transfer_text(content: &[ContentPart], to: &str) -> bool {
633	    let [ContentPart::Text { text }] = content else {
634	        return false;
635	    };
636	    [
637	        format!("transferred to {to}"),
638	        format!("transfer not performed: this response already transferred to {to}"),
639	        format!("transfer failed: {to} did not start"),
640	    ]
641	    .contains(text)
642	}
643	
644	/// Whether `item` is a tool result with exactly the synthetic cancel text.
645	fn is_cancel_text(item: &Item) -> bool {
646	    matches!(item, Item::ToolResult { content, .. }
647	        if matches!(content.as_slice(), [ContentPart::Text { text }] if text == CANCELLED_TOOL_CALL_TEXT))
648	}
649	
650	/// Project each event to its message, in event order, with no repair.
651	///
652	/// Returns the messages and, for each message, the index of the event that
653	/// produced it (`sources`). The summary message of a `Compacted` event gets
654	/// the index of that `Compacted` event.
655	fn project_events(events: &[SessionEvent]) -> (Vec<Item>, Vec<usize>) {
656	    let mut messages: Vec<Item> = Vec::new();
657	    let mut sources: Vec<usize> = Vec::new();
658	    // Parallel vec: contributions[i] = number of messages event i produced.
659	    // Needed because Compacted has to undo the message yield of the previous
660	    // N events, and yield varies per variant (HandoffOccurred = 0, others = 1).
661	    let mut contributions: Vec<usize> = Vec::new();
662	
663	    for (at, ev) in events.iter().enumerate() {
664	        match ev {
665	            SessionEvent::UserMessage { content, .. } => {
666	                messages.push(Item::UserMessage {
667	                    content: content.clone(),
668	                });
669	                sources.push(at);
670	                contributions.push(1);
671	            }
672	            SessionEvent::AssistantMessage { content, agent, .. } => {
673	                messages.push(Item::AssistantMessage {
674	                    content: content.clone(),
675	                    agent: Some(agent.clone()),
676	                });
677	                sources.push(at);
678	                contributions.push(1);
679	            }
680	            SessionEvent::ToolCalled {
681	                call_id,
682	                name,
683	                args,
684	                ..
685	            } => {
686	                messages.push(Item::ToolCall {
687	                    call_id: call_id.clone(),
688	                    name: name.clone(),
689	                    args: args.clone(),
690	                });
691	                sources.push(at);
692	                contributions.push(1);
693	            }
694	            SessionEvent::ToolReturned {
695	                call_id, content, ..
696	            } => {
697	                messages.push(Item::ToolResult {
698	                    call_id: call_id.clone(),
699	                    content: content.clone(),
700	                });
701	                sources.push(at);
702	                contributions.push(1);
703	            }
704	            SessionEvent::HandoffOccurred { .. } => {
705	                // Audit-only event; no message produced.
706	                contributions.push(0);
707	            }
708	            SessionEvent::ToolDeferred { .. } => {
709	                // Audit and resume record; no message produced.
710	                contributions.push(0);
711	            }
712	            SessionEvent::Compacted {
713	                summary,
714	                original_count,
715	                ..
716	            } => {
717	                let n = usize::try_from(*original_count).unwrap_or(usize::MAX);
718	                if n == 0 {
719	                    tracing::warn!(
720	                        target: "paigasus::core::session",
721	                        "Compacted event with original_count = 0; emitting summary as a system message without compacting any history (likely producer bug — use SessionEvent::compacted with a positive count)"
722	                    );
723	                }
724	                if n > contributions.len() {
725	                    tracing::warn!(
726	                        target: "paigasus::core::session",
727	                        original_count = n,
728	                        events_seen = contributions.len(),
729	                        "Compacted event references more events than have been seen; treating as 'compact everything observed so far' (likely corrupt log)"

729	                        "Compacted event references more events than have been seen; treating as 'compact everything observed so far' (likely corrupt log)"
730	                    );
731	                }
732	                let drop_from_idx = contributions.len().saturating_sub(n);
733	                let drop_msg_count: usize = contributions[drop_from_idx..].iter().sum();
734	                let new_len = messages.len() - drop_msg_count;
735	                messages.truncate(new_len);
736	                sources.truncate(new_len);
737	                // Drop the contribution entries the Compacted event subsumed
738	                // so a subsequent Compacted's `n` indexes back over the
739	                // remaining events, not the already-summarized ones.
740	                contributions.truncate(drop_from_idx);
741	                messages.push(Item::System {
742	                    content: vec![ContentPart::Text {
743	                        text: summary.clone(),
744	                    }],
745	                });
746	                sources.push(at);
747	                contributions.push(1);
748	            }
749	        }
750	    }
751	
752	    (messages, sources)
753	}
754	
755	/// Accumulates one run's semantic items as [`SessionEvent`]s for the runner to
756	/// persist at run exit.
757	///
758	/// The runner pre-seeds the recorder with the run's `AgentInput` messages (the
759	/// new turn — which the agent does not re-emit on its event stream), then feeds
