1	//! [`BedrockModel`] — the Bedrock Converse API model handle.
2	//!
3	//! Wraps an `Arc<Config>` so that the model handle is `Clone + Send + Sync`
4	//! and the `BoxStream` returned by `invoke` can be `'static + Send`.
5	
6	use std::sync::Arc;
7	
8	use async_stream::stream;
9	use async_trait::async_trait;
10	use futures_core::stream::BoxStream;
11	use paigasus_helikon_core::{
12	    CancellationToken, Model, ModelCapabilities, ModelError, ModelEvent, ModelRequest,
13	};
14	
15	use crate::builder::Config;
16	use crate::error::{map_sdk_error, map_sdk_http_error};
17	use crate::stream::StreamTranslator;
18	use crate::translate::build_request;
19	
20	// ── BedrockModel ──────────────────────────────────────────────────────────────
21	
22	/// An Amazon Bedrock Converse API model handle.
23	///
24	/// Construct via [`BedrockModel::converse`] (sync builder) or
25	/// [`BedrockModel::from_env`] (async, loads AWS config from the environment).
26	///
27	/// The handle is `Clone + Send + Sync` because it holds only an `Arc<Config>`.
28	#[derive(Debug, Clone)]
29	pub struct BedrockModel(pub(crate) Arc<Config>);
30	
31	// ── Model impl ────────────────────────────────────────────────────────────────
32	
33	#[async_trait]
34	impl Model for BedrockModel {
35	    /// Stream model events from Amazon Bedrock's Converse API.
36	    ///
37	    /// The returned stream is `'static + Send`.
38	    ///
39	    /// **Cancellation contract:** when `cancel` fires mid-stream, the stream
40	    /// ends immediately without emitting a final `Finish` event (per the core
41	    /// `Model` trait contract).
42	    async fn invoke(
43	        &self,
44	        request: ModelRequest,
45	        cancel: CancellationToken,
46	    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
47	        // Translate the core request into Bedrock wire format (early error on
48	        // translation failure — before we open any network connection).
49	        let prepared = build_request(&self.0, &request)?;
50	
51	        let synthesizing = prepared.synthesizing;
52	        let client = self.0.client.clone();
53	
54	        // Build the fluent ConverseStream request from the prepared parts.
55	        let fluent = client
56	            .converse_stream()
57	            .model_id(&prepared.model_id)
58	            .set_messages(Some(prepared.messages))
59	            .set_system(if prepared.system.is_empty() {
60	                None
61	            } else {
62	                Some(prepared.system)
63	            })
64	            .set_tool_config(prepared.tool_config)
65	            .set_inference_config(prepared.inference_config);
66	
67	        let s = stream! {
68	            // Send the ConverseStream request and obtain the event receiver.
69	            // Guard with a cancellation check (biased: cancel arm wins) so that
70	            // a token already fired — or one that fires during the HTTP send —
71	            // aborts cleanly without opening a dangling Bedrock stream and
72	            // without emitting Finish (per the Model::invoke cancellation contract).
73	            let output = tokio::select! {
74	                biased;
75	                _ = cancel.cancelled() => { return; }
76	                result = fluent.send() => {
77	                    // map_sdk_http_error: fluent.send() returns
78	                    // SdkError<_, HttpResponse>, so we can extract Retry-After headers.
79	                    match result {
80	                        Ok(o) => o,
81	                        Err(e) => {
82	                            yield Err(map_sdk_http_error(e));
83	                            return;
84	                        }
85	                    }
86	                }
87	            };
88	
89	            let mut receiver = output.stream;
90	            let mut translator = StreamTranslator::new(synthesizing);
91	
92	            loop {
93	                let next = tokio::select! {
94	                    biased;
95	                    _ = cancel.cancelled() => {
96	                        // Cancellation: end stream without emitting Finish.
97	                        return;
98	                    }
99	                    r = receiver.recv() => r,
100	                };
101	
102	                match next {
103	                    // Stream exhausted normally (EOF).
104	                    // Flush any buffered stop reason that arrived without a
105	                    // subsequent Metadata event so the consumer always sees
106	                    // a terminal Finish.
107	                    Ok(None) => {
108	                        if let Some(terminal) = translator.finish() {
109	                            yield terminal;
110	                        }
111	                        return;
112	                    }
113	                    // Good event — feed through translator and yield results.
114	                    Ok(Some(event)) => {
115	                        for result in translator.consume(event) {
116	                            yield result;
117	                        }
118	                    }
119	                    // Transport-level error on the event stream.
120	                    Err(e) => {
121	                        yield Err(map_sdk_error(e));
122	                        return;
123	                    }
124	                }
125	            }
126	        };
127	
128	        Ok(Box::pin(s))
129	    }
130	
131	    fn capabilities(&self) -> ModelCapabilities {
132	        self.0.capabilities
133	    }
134	
135	    fn provider(&self) -> &str {
136	        "bedrock"
137	    }
138	
139	    fn model(&self) -> &str {
140	        &self.0.model_id
141	    }
142	}
143	
144	// ── Unit tests (descriptor + capability + cancellation contract) ──────────────
145	
146	#[cfg(test)]
147	mod tests {
148	    use super::*;
149	    use aws_config::{BehaviorVersion, Region};
150	    use futures_core::stream::BoxStream;
151	
152	    // ── Cancellation-wrapper helper (test-only) ───────────────────────────────
153	
154	    /// Wrap any `Stream<Item = Result<ModelEvent, ModelError>>` with a
155	    /// `CancellationToken` guard.
156	    ///
157	    /// When `cancel` fires, the returned stream ends immediately **without**
158	    /// emitting a `Finish` event — matching the `Model::invoke` cancellation
159	    /// contract.
160	    fn drive_stream_with_token<S>(
161	        source: S,
162	        cancel: CancellationToken,
163	    ) -> BoxStream<'static, Result<ModelEvent, ModelError>>
164	    where
165	        S: futures_core::Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static,
166	    {
167	        Box::pin(stream! {
168	            tokio::pin!(source);
169	            loop {
170	                let next = tokio::select! {
171	                    biased;
172	                    _ = cancel.cancelled() => return,
173	                    r = futures_util::StreamExt::next(&mut source) => r,
174	                };
175	                match next {
176	                    None => return,
177	                    Some(v) => yield v,
178	                }
179	            }
180	        })
181	    }
182	
183	    fn offline_model(model_id: &str) -> BedrockModel {
184	        let rt = tokio::runtime::Builder::new_current_thread()
185	            .enable_all()
186	            .build()
187	            .expect("tokio runtime");
188	        rt.block_on(async {
189	            let sdk_cfg = aws_config::defaults(BehaviorVersion::v2026_11_17())
190	                .region(Region::new("us-east-1"))
191	                .test_credentials()
192	                .load()
193	                .await;
194	            BedrockModel::converse(model_id)
195	                .sdk_config(&sdk_cfg)
196	                .build()
197	                .expect("build offline model")
198	        })
199	    }
200	
201	    #[test]
202	    fn provider_returns_bedrock() {
203	        let m = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
204	        assert_eq!(m.provider(), "bedrock");
205	    }
206	
207	    #[test]
208	    fn model_returns_configured_id() {
209	        let id = "anthropic.claude-3-5-sonnet-20241022-v2:0";
210	        let m = offline_model(id);
211	        assert_eq!(m.model(), id);
212	    }
213	
214	    #[test]
215	    fn capabilities_matches_caps_for_anthropic() {
216	        let m = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
217	        let caps = m.capabilities();
218	        assert!(caps.streaming);
219	        assert!(caps.tools);
220	        assert!(caps.structured_output);
221	        assert!(
222	            !caps.vision,
223	            "vision not advertised (no image-block mapping)"
224	        );
225	    }
226	
227	    #[test]
228	    fn model_is_clone() {
229	        let m = offline_model("amazon.nova-pro-v1:0");
230	        let m2 = m.clone();
231	        assert_eq!(m.model(), m2.model());
232	    }
233	
234	    // ── Cancellation contract tests ───────────────────────────────────────────
235	
236	    use futures_core::Stream;
237	    use futures_util::StreamExt;
238	
239	    /// Build a stream that yields `n` `TokenDelta` events then ends.
240	    fn token_stream(
241	        n: usize,
242	    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
243	        let events: Vec<Result<ModelEvent, ModelError>> = (0..n)
244	            .map(|i| {
245	                Ok(ModelEvent::TokenDelta {
246	                    text: format!("chunk-{i}"),
247	                })
248	            })
249	            .collect();
250	        futures_util::stream::iter(events)
251	    }
252	
253	    /// Build a stream that yields `n` `TokenDelta` events then a `Finish` event.
254	    fn token_stream_with_finish(
255	        n: usize,
256	    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
257	        use paigasus_helikon_core::FinishReason;
258	        let mut events: Vec<Result<ModelEvent, ModelError>> = (0..n)
259	            .map(|i| {
260	                Ok(ModelEvent::TokenDelta {
261	                    text: format!("chunk-{i}"),
262	                })
263	            })
264	            .collect();
265	        events.push(Ok(ModelEvent::Finish {
266	            reason: FinishReason::Stop,
267	        }));
268	        futures_util::stream::iter(events)
269	    }
270	
271	    #[tokio::test]
272	    async fn cancel_before_stream_ends_no_finish() {
273	        let cancel = CancellationToken::new();
274	        let source = token_stream(10);
275	
276	        // Cancel immediately — the stream should yield 0 events and no Finish.
277	        cancel.cancel();
278	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
279	
280	        let has_finish = events
281	            .iter()
282	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
283	        assert!(!has_finish, "cancelled stream must not emit Finish");
284	    }
285	
286	    #[tokio::test]
287	    async fn cancel_mid_stream_no_finish() {
288	        use std::sync::atomic::{AtomicBool, Ordering};
289	        use std::sync::Arc;
290	
291	        let cancel = CancellationToken::new();
292	        let cancel_clone = cancel.clone();
293	
294	        // A stream that cancels itself after yielding the first token.
295	        let cancelled = Arc::new(AtomicBool::new(false));
296	        let cancelled_clone = cancelled.clone();
297	
298	        let source = async_stream::stream! {
299	            yield Ok::<ModelEvent, ModelError>(ModelEvent::TokenDelta { text: "first".to_owned() });
300	            // Signal cancellation after the first token.
301	            if !cancelled_clone.swap(true, Ordering::SeqCst) {
302	                cancel_clone.cancel();
303	            }
304	            // `biased;` in drive_stream_with_token's tokio::select! checks the
305	            // cancel arm first on every iteration, so once cancel() fires the
306	            // driver exits before polling the source again — making this
307	            // single-threaded ordering deterministic and guaranteeing no Finish
308	            // is emitted after cancel.
309	            yield Ok(ModelEvent::TokenDelta { text: "second".to_owned() });
310	            yield Ok(ModelEvent::Finish { reason: paigasus_helikon_core::FinishReason::Stop });
311	        };
312	
313	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
314	
315	        let has_finish = events
316	            .iter()
317	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
318	        assert!(!has_finish, "mid-stream cancel must not emit Finish");
319	    }
320	
321	    #[tokio::test]
322	    async fn uncancelled_stream_emits_finish() {
323	        let cancel = CancellationToken::new();
324	        let source = token_stream_with_finish(3);
325	
326	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
327	
328	        let has_finish = events
329	            .iter()
330	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
331	        assert!(has_finish, "uncancelled stream must emit Finish");
332	        // All 3 token deltas + finish = 4 events.
333	        assert_eq!(events.len(), 4, "expected 3 tokens + 1 finish");
334	    }
335	
336	    #[tokio::test]
337	    async fn cancel_does_not_drop_events_already_yielded() {
338	        let cancel = CancellationToken::new();
339	        // 5 events, no finish.  Don't cancel — all should arrive.
340	        let source = token_stream(5);
341	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
342	        assert_eq!(events.len(), 5, "all events must arrive when not cancelled");
343	    }
344	}
