1	//! Model capability flags for Bedrock model families.
2	//!
3	//! Returns conservative defaults for unknown families; callers may override
4	//! via [`crate::BedrockModelBuilder::capabilities`].
5	
6	use crate::family::ModelFamily;
7	use paigasus_helikon_core::ModelCapabilities;
8	
9	/// Return the capability flags for a family.
10	///
11	/// The `structured_output` flag is set for families that support forced
12	/// tool-choice (the mechanism used to synthesize structured output on Bedrock).
13	/// No per-family `max_output_tokens` default is returned; omitting
14	/// `inferenceConfig.maxTokens` lets the model apply its own correct default,
15	/// which avoids `ValidationException` on models whose limit is below any
16	/// hardcoded value.  Callers may supply an explicit default via
17	/// [`crate::BedrockModelBuilder::max_output_tokens_default`].
18	pub(crate) fn caps_for(family: ModelFamily) -> ModelCapabilities {
19	    match family {
20	        ModelFamily::Anthropic => ModelCapabilities::empty()
21	            .with_streaming()
22	            .with_tools()
23	            .with_parallel_tool_calls()
24	            .with_structured_output(),
25	        ModelFamily::AmazonNova => ModelCapabilities::empty()
26	            .with_streaming()
27	            .with_tools()
28	            .with_parallel_tool_calls()
29	            .with_structured_output(),
30	        ModelFamily::AmazonTitan => ModelCapabilities::empty().with_streaming().with_tools(),
31	        ModelFamily::Llama => ModelCapabilities::empty().with_streaming().with_tools(),
32	        ModelFamily::Mistral => ModelCapabilities::empty()
